// A fifth-language A2A agent for interop testing: a2a-rs (a2a-server-lf 0.4.4, A2A v1.0), HTTP+JSON/REST only,
// mounted under /rest the way the SDK's own helloworld is (so the card's interface URL carries a path).
// Same behaviour contract as node-agent/agent.mjs. If ANTHROPIC_API_KEY is set the reply is generated by Claude
// (raw Messages API; there is no official Anthropic Rust SDK), otherwise by a deterministic stub; every reply is
// prefixed "[claude]" or "[stub]" so a run can never silently pass off the stub as the model.
//
//   text "slow ..."    -> WORKING for ~8s (cancellable), then COMPLETED
//   text "need input"  -> INPUT_REQUIRED; a follow-up on the same task completes it
//   text "msg: ..."    -> a direct Message reply (no task)
//   anything else      -> COMPLETED task with one text artifact
use std::collections::HashSet;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use a2a::*;
use a2a_server::*;
use futures::stream::{self, BoxStream};

struct Llm {
    http: reqwest::Client,
    key: Option<String>,
    model: String,
}

impl Llm {
    async fn answer(&self, prompt: &str) -> String {
        let Some(key) = &self.key else { return format!("[stub] echo: {prompt}") };
        let body = serde_json::json!({
            "model": self.model, "max_tokens": 200,
            "messages": [{"role": "user", "content": prompt}],
        });
        let res = self.http.post("https://api.anthropic.com/v1/messages")
            .header("x-api-key", key).header("anthropic-version", "2023-06-01")
            .json(&body).send().await;
        match res {
            Ok(r) => {
                let v: serde_json::Value = r.json().await.unwrap_or_default();
                let text: String = v["content"].as_array().map(|blocks| blocks.iter()
                    .filter(|b| b["type"] == "text").filter_map(|b| b["text"].as_str()).collect())
                    .unwrap_or_default();
                if text.is_empty() { format!("[claude-error] {v}") } else { format!("[claude] {text}") }
            }
            Err(e) => format!("[claude-error] {e}"),
        }
    }
}

struct Executor {
    llm: Arc<Llm>,
    cancelled: Arc<Mutex<HashSet<String>>>,
}

fn text_of(m: &Option<Message>) -> String {
    m.as_ref().map(|m| m.parts.iter().filter_map(|p| match &p.content {
        PartContent::Text(t) => Some(t.clone()),
        _ => None,
    }).collect()).unwrap_or_default()
}

fn agent_msg(text: &str, task: Option<&str>, ctx: &str) -> Message {
    Message {
        role: Role::Agent, message_id: new_message_id(), task_id: task.map(|t| t.into()),
        context_id: Some(ctx.into()), parts: vec![Part::text(text)], metadata: None,
        extensions: None, reference_task_ids: None,
    }
}

fn status(task: &str, ctx: &str, state: TaskState, message: Option<Message>) -> StreamResponse {
    StreamResponse::StatusUpdate(TaskStatusUpdateEvent {
        task_id: task.into(), context_id: ctx.into(),
        status: TaskStatus { state, message, timestamp: Some(chrono::Utc::now()) }, metadata: None,
    })
}

impl AgentExecutor for Executor {
    fn execute(&self, ctx: ExecutorContext) -> BoxStream<'static, Result<StreamResponse, A2AError>> {
        let (tx, rx) = tokio::sync::mpsc::channel(16);
        let llm = self.llm.clone();
        let cancelled = self.cancelled.clone();
        tokio::spawn(async move {
            let text = text_of(&ctx.message);
            let (tid, cid) = ctx.task_info();
            // Not ctx.stored_task: a2a-rs stores the new task before execute, so it is Some on the first turn too.
            let continuing = ctx.message.as_ref().is_some_and(|m| m.task_id.is_some());
            if let Some(q) = text.strip_prefix("msg:") {
                let reply = llm.answer(q).await;
                let _ = tx.send(Ok(StreamResponse::Message(agent_msg(&reply, None, &cid)))).await;
                return;
            }
            if text.contains("need input") && !continuing {
                let ask = agent_msg("Which city?", Some(&tid), &cid);
                let _ = tx.send(Ok(status(&tid, &cid, TaskState::InputRequired, Some(ask)))).await;
                return;
            }
            let _ = tx.send(Ok(status(&tid, &cid, TaskState::Working, Some(agent_msg("Working", Some(&tid), &cid))))).await;
            if text.starts_with("slow") {
                for _ in 0..16 {
                    tokio::time::sleep(Duration::from_millis(500)).await;
                    if cancelled.lock().unwrap().remove(&tid) {
                        let _ = tx.send(Ok(status(&tid, &cid, TaskState::Canceled, None))).await;
                        return;
                    }
                }
            }
            let reply = llm.answer(&text).await;
            let art = TaskArtifactUpdateEvent {
                task_id: tid.clone(), context_id: cid.clone(),
                artifact: Artifact { artifact_id: new_artifact_id(), name: Some("Result".into()), description: None,
                                     parts: vec![Part::text(reply)], metadata: None, extensions: None },
                append: Some(false), last_chunk: Some(true), metadata: None,
            };
            let _ = tx.send(Ok(StreamResponse::ArtifactUpdate(art))).await;
            let _ = tx.send(Ok(status(&tid, &cid, TaskState::Completed, None))).await;
        });
        Box::pin(tokio_stream_from(rx))
    }

    fn cancel(&self, ctx: ExecutorContext) -> BoxStream<'static, Result<StreamResponse, A2AError>> {
        let (tid, cid) = ctx.task_info();
        self.cancelled.lock().unwrap().insert(tid.clone());
        Box::pin(stream::once(async move { Ok(status(&tid, &cid, TaskState::Canceled, None)) }))
    }
}

fn tokio_stream_from<T: Send + 'static>(mut rx: tokio::sync::mpsc::Receiver<T>) -> impl futures::Stream<Item = T> {
    stream::poll_fn(move |cx| rx.poll_recv(cx))
}

#[tokio::main]
async fn main() {
    let port: u16 = std::env::args().nth(1).and_then(|p| p.parse().ok()).unwrap_or(9804);
    // The URL the card advertises; PUBLIC_HOST lets a containerised agent hand out an address its callers can reach.
    let host = std::env::var("PUBLIC_HOST").unwrap_or_else(|_| "localhost".into());
    let llm = Arc::new(Llm {
        http: reqwest::Client::new(),
        key: std::env::var("ANTHROPIC_API_KEY").ok().filter(|k| !k.is_empty()),
        model: std::env::var("CLAUDE_MODEL").unwrap_or_else(|_| "claude-haiku-4-5".into()),
    });
    let mode = if llm.key.is_some() { format!("Claude {}", llm.model) } else { "stub".into() };

    let mut card = AgentCard {
        name: "Rust A2A Interop Agent".into(),
        description: format!("a2a-rs agent (HTTP+JSON only), {mode}"),
        version: "1.0.0".into(),
        provider: None,
        capabilities: AgentCapabilities { streaming: Some(true), push_notifications: Some(true), extensions: None, extended_agent_card: None },
        skills: vec![AgentSkill { id: "chat".into(), name: "Chat".into(), description: "Answers questions".into(),
                                  tags: vec!["chat".into()], examples: None, input_modes: None, output_modes: None, security_requirements: None }],
        default_input_modes: vec!["text/plain".into()],
        default_output_modes: vec!["text/plain".into()],
        supported_interfaces: vec![AgentInterface::new(format!("http://{host}:{port}/rest"), TRANSPORT_PROTOCOL_HTTP_JSON)],
        security_schemes: None, security_requirements: None, documentation_url: None, icon_url: None, signatures: None,
    };
    if std::env::var("TRAILING_SLASH").as_deref() == Ok("1") {
        card.supported_interfaces[0].url.push('/');
    }

    // validate_urls off: the interop push receiver is on localhost, which the default SSRF guard refuses.
    let sender = HttpPushSender::new(Some(HttpPushSenderConfig { validate_urls: false, ..Default::default() }));
    let handler = Arc::new(DefaultRequestHandler::new(Executor { llm, cancelled: Default::default() }, InMemoryTaskStore::new())
        .with_push_notifications(InMemoryPushConfigStore::new(), sender));
    let app = axum::Router::new()
        .nest("/rest", a2a_server::rest::rest_router(handler))
        .merge(a2a_server::agent_card::agent_card_router(Arc::new(StaticAgentCard::new(card))));
    let l = tokio::net::TcpListener::bind(("0.0.0.0", port)).await.unwrap();
    println!("rust agent on http://{host}:{port}/rest ({mode})");
    axum::serve(l, app).await.unwrap();
}
